/*
 * SVM-only diagnostics. Each returns 0 on VMX so the caller skips the print
 * entirely rather than reporting fabricated zeros.
 *
 * These are deliberately NOT ported. hype_svm_debug_state_t is an SVM
 * investigation artifact -- EXITINFO2, EXITINTINFO, NRIP, G_PAT are VMCB fields
 * with no VMCS counterpart, and several exist specifically to answer questions
 * about AMD save-area behaviour. Likewise the EVENTINJ-collision and MTRR
 * counters are file-scope tallies inside svm_vcpu.c. Porting an SVM debugging
 * apparatus is not what Intel parity requires; running a guest is.
 */
/*
 * #249: the SVM-named struct in a vendor-neutral shim is deliberate, not an
 * oversight. It IS the SVM snapshot -- EXITINFO2 / EXITINTINFO / NRIP / G_PAT have
 * no VMCS counterpart -- so there is no neutral type to promote it to. The shim
 * exists to answer "is that snapshot available?", and returns 0 on VMX.
 */
static int vmm_get_debug_state(hype_vmm_kind_t kind, hype_vcpu_ctx_t *ctx,
                               hype_svm_debug_state_t *out) {
    if (kind == HYPE_VMM_KIND_VMX) {
        /*
         * #520: this used to zero the struct and return 0 -- "nothing here" -- which meant every
         * caller that dumps guest state on a fault, including the AP's own exception dump,
         * printed nothing on Intel. Three rounds of Intel AP debugging had to be inferred from
         * exit-reason counters because of it. The VMX side reads its VMCS now, so a fault on
         * either backend explains itself.
         *
         * cr2 and nrip stay zero there: neither has a VMCS equivalent (see the definition).
         */
        hype_vmx_vcpu_get_debug_state(ctx, out);
        return 1;
    }
    hype_svm_vcpu_get_debug_state(ctx, out);
    return 1;
}
/*
 * #611: GPRs are plain memory in both backends' ctx (never a VMCS/VMCB field), so
 * hype_{vmx,svm}_vcpu_get_gpr() already read them directly with no owner-core gating -- see
 * their definitions in vmcs_hw.c/svm_vcpu.c. This is only the vendor dispatch, matching the
 * other vmm_get_* shims.
 */
static uint64_t vmm_get_gpr(hype_vmm_kind_t kind, hype_vcpu_ctx_t *ctx, unsigned idx) {
    if (kind == HYPE_VMM_KIND_VMX) {
        return hype_vmx_vcpu_get_gpr(ctx, idx);
    }
    return hype_svm_vcpu_get_gpr(ctx, idx);
}
/*
 * #563: takes a ctx now, because the counters are per-vCPU. As file-globals they summed every vCPU
 * of every VM, so the INTDIAG line could say injections were being deferred but never WHOSE -- the
 * counter built to attribute a lost interrupt was the one that could not.
 */
static int vmm_get_int_diag(hype_vmm_kind_t kind, hype_vcpu_ctx_t *ctx,
                            unsigned long long *eventinj, unsigned long long *defer,
                            unsigned long long *window, unsigned long long *overwrite) {
    if (kind == HYPE_VMM_KIND_VMX) {
        hype_vmx_vcpu_get_int_diag(ctx, eventinj, defer, window, overwrite);
        return 1;
    }
    hype_svm_vcpu_get_int_diag(ctx, eventinj, defer, window, overwrite);
    return 1;
}
